<?php
declare(strict_types=1);
require_once dirname(__DIR__) . '/classes/GreenPortalDatabase.php';
require_once dirname(__DIR__) . '/classes/IdiomaService.php';
require_once dirname(__DIR__) . '/classes/UsuarioSessao.php';
require_once dirname(__DIR__) . '/classes/PermissaoTransacao.php';
require_once dirname(__DIR__) . '/classes/TransactionSecurity.php';
if (session_status() !== PHP_SESSION_ACTIVE) session_start();
if (empty($_SESSION['autenticado']) || empty($_SESSION['tenant']['banco_dados'])) { http_response_code(401); exit(IdiomaService::t('responsabilidades.erro.sessao', ['pt' => 'Sessão expirada.', 'en' => 'Your session has expired.', 'es' => 'Su sesión expiró.'])); }
$env = GreenPortalDatabase::env();
$pdo = TransactionSecurity::connect('MODULOLEGAL_TREINAMENTOS');
if (!UsuarioSessao::atualizar($pdo, $_SESSION)) { http_response_code(401); exit(IdiomaService::t('responsabilidades.erro.sessao', ['pt' => 'Sessão expirada.', 'en' => 'Your session has expired.', 'es' => 'Su sesión expiró.'])); }
$permission = PermissaoTransacao::obter('MODULOLEGAL_TREINAMENTOS');
if (!$permission['pode_visualizar']) { http_response_code(403); exit(IdiomaService::t('responsabilidades.erro.sem_permissao', ['pt' => 'Sem permissão para consultar responsabilidades.', 'en' => 'Not allowed to view responsibilities.', 'es' => 'Sin permiso para consultar responsabilidades.'])); }
$filters = json_decode((string)($_GET['filtros'] ?? '{}'), true) ?: [];
$id = filter_var($filters['CODTREINAMENTO'] ?? $_GET['CODTREINAMENTO'] ?? null, FILTER_VALIDATE_INT, ['options' => ['min_range' => 1]]);
if (!$id) { http_response_code(400); exit(IdiomaService::t('responsabilidades.erro.treinamento_invalido', ['pt' => 'Treinamento inválido.', 'en' => 'Invalid training.', 'es' => 'Capacitación inválida.'])); }
$json = static fn(mixed $v): string => json_encode($v, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
$e = static fn(mixed $v): string => htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8');
$call = static fn(PDO $db, string $sql, array $params = []): array => GreenPortalDatabase::call($db, $sql, $params);
$types = $call($pdo, 'CALL sp_crud_select(:tabela,:filtros,NULL,100,0)', ['tabela' => 'vw_responsabilidade_tipos', 'filtros' => $json(['MODULO_CODIGO' => 'TREINAMENTO', 'ATIVO' => 1])]);
$users = $call($pdo, 'CALL sp_crud_select(:tabela,:filtros,NULL,10000,0)', ['tabela' => 'vw_responsabilidade_usuarios_ativos', 'filtros' => $json([])]);
$groups = $call($pdo, 'CALL sp_crud_select(:tabela,:filtros,NULL,10000,0)', ['tabela' => 'vw_responsabilidade_grupos_ativos', 'filtros' => $json([])]);
$context = $call($pdo, 'CALL sp_crud_select(:tabela,:filtros,NULL,1,0)', ['tabela' => 'vw_modulolegal_treinamentos_grid', 'filtros' => $json(['CODTREINAMENTO' => $id])])[0] ?? [];
if (!$context) { http_response_code(404); exit(IdiomaService::t('responsabilidades.erro.treinamento_nao_localizado', ['pt' => 'Treinamento não localizado.', 'en' => 'Training not found.', 'es' => 'Capacitación no encontrada.'])); }
$moduleId = (int)($types[0]['CODMODULO'] ?? 0); $message = ''; $error = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST' && ($_POST['action'] ?? '') === 'save_rows') {
    if (!$permission['pode_editar'] && !$permission['pode_incluir'] && !$permission['pode_excluir']) { http_response_code(403); exit(IdiomaService::t('responsabilidades.erro.sem_permissao_alterar', ['pt' => 'Sem permissão para alterar responsabilidades.', 'en' => 'Not allowed to change responsibilities.', 'es' => 'Sin permiso para modificar responsabilidades.'])); }
    try {
        $existing = $call($pdo, 'CALL sp_crud_select(:tabela,:filtros,NULL,1000,0)', ['tabela' => 'vw_responsabilidade_ml_treinamentos', 'filtros' => $json(['CODTREINAMENTO' => $id, 'ATIVO' => 1])]);
        $posted = array_map('strval', array_keys((array)($_POST['rows'] ?? [])));
        foreach ($existing as $old) if (!in_array((string)$old['CODATRIBUICAO'], $posted, true) && $permission['pode_excluir']) {
            $deleteKey = $json(['CODATRIBUICAO' => (int)$old['CODATRIBUICAO']]);
            $deleteData = $json(['ATIVO' => 0, 'CODUSUARIOALTERACAO' => (int)$_SESSION['usuario']['codusuario']]);
            $call($pdo, 'CALL sp_crud_update(:tabela,:chave,:dados)', ['tabela' => 'responsabilidade_atribuicoes', 'chave' => $deleteKey, 'dados' => $deleteData]);
        }
        $validTypes = array_map('intval', array_column($types, 'CODTIPORESPONSABILIDADE'));
        foreach ((array)($_POST['rows'] ?? []) as $key => $row) {
            $rid = ctype_digit((string)$key) ? (int)$key : 0; $destination = strtoupper(trim((string)($row['TIPO_DESTINO'] ?? ''))); $type = (int)($row['CODTIPORESPONSABILIDADE'] ?? 0);
            $user = $destination === 'USUARIO' ? max(0, (int)($row['CODUSUARIO'] ?? 0)) : null; $group = $destination === 'GRUPO' ? max(0, (int)($row['CODGRUPO'] ?? 0)) : null;
            if (!$type || !in_array($type, $validTypes, true) || !in_array($destination, ['USUARIO', 'GRUPO'], true) || ($destination === 'USUARIO' && !$user) || ($destination === 'GRUPO' && !$group)) throw new RuntimeException(IdiomaService::t('responsabilidades.erro.preencha', ['pt' => 'Preencha finalidade e destino em todas as linhas.', 'en' => 'Fill in purpose and assignee on every row.', 'es' => 'Complete finalidad y destino en todas las líneas.']));
            $from = trim((string)($row['VALIDO_DE'] ?? '')) ?: date('Y-m-d'); $to = trim((string)($row['VALIDO_ATE'] ?? '')) ?: null;
            $params = ['atribuicao' => $rid ?: null, 'modulo' => $moduleId, 'origem' => 'DIRETA', 'tipo' => $type, 'categoria' => null, 'entidade' => 'ml_treinamentos', 'registro' => (string)$id, 'destino' => $destination, 'usuario' => $user, 'grupo' => $group, 'de' => $from, 'ate' => $to];
            $call($pdo, 'CALL sp_responsabilidade_validar_duplicidade(:atribuicao,:modulo,:origem,:tipo,:categoria,:entidade,:registro,:destino,:usuario,:grupo,:de,:ate)', $params);
            $data = ['CODMODULO' => $moduleId, 'ORIGEM' => 'DIRETA', 'CODTIPORESPONSABILIDADE' => $type, 'ENTIDADE' => 'ml_treinamentos', 'REGISTRO_ID' => (string)$id, 'TIPO_DESTINO' => $destination, 'CODUSUARIO' => $user, 'CODGRUPO' => $group, 'PRIORIDADE' => (int)($row['PRIORIDADE'] ?? 0), 'PRINCIPAL' => !empty($row['PRINCIPAL']) ? 1 : 0, 'VALIDO_DE' => $from, 'VALIDO_ATE' => $to, 'ATIVO' => 1, 'OBSERVACAO' => trim((string)($row['OBSERVACAO'] ?? '')), 'CODUSUARIOALTERACAO' => (int)$_SESSION['usuario']['codusuario']];
            if ($rid && $permission['pode_editar']) $call($pdo, 'CALL sp_crud_update(:tabela,:chave,:dados)', ['tabela' => 'responsabilidade_atribuicoes', 'chave' => $json(['CODATRIBUICAO' => $rid]), 'dados' => $json($data)]);
            elseif (!$rid && $permission['pode_incluir']) $call($pdo, 'CALL sp_crud_insert(:tabela,:dados)', ['tabela' => 'responsabilidade_atribuicoes', 'dados' => $json($data)]);
        }
        $message = IdiomaService::t('responsabilidades.msg.salvas', ['pt' => 'Responsabilidades salvas com sucesso.', 'en' => 'Responsibilities saved successfully.', 'es' => 'Responsabilidades guardadas con éxito.']);
    } catch (Throwable $ex) { $error = IdiomaService::t('responsabilidades.erro.salvar', ['pt' => 'Não foi possível salvar as responsabilidades. Verifique os dados informados.', 'en' => 'Could not save the responsibilities. Check the data entered.', 'es' => 'No fue posible guardar las responsabilidades. Verifique los datos informados.']); }
}
$rows = $call($pdo, 'CALL sp_crud_select(:tabela,:filtros,NULL,1000,0)', ['tabela' => 'vw_responsabilidade_ml_treinamentos', 'filtros' => $json(['CODTREINAMENTO' => $id, 'ATIVO' => 1])]);
$assignedUserIds = array_values(array_unique(array_filter(array_map(static fn(array $row): string => (string)($row['CODUSUARIO'] ?? ''), $rows))));
$assignedGroupIds = array_values(array_unique(array_filter(array_map(static fn(array $row): string => (string)($row['CODGRUPO'] ?? ''), $rows))));
echo '<script>window.mlResponsibilityPermission=' . json_encode(['include' => !empty($permission['pode_incluir']), 'edit' => !empty($permission['pode_editar']), 'delete' => !empty($permission['pode_excluir'])], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) . ';</script>';
register_shutdown_function(static function () use ($assignedUserIds, $assignedGroupIds): void {
    echo '' . IdiomaService::script([], ['responsabilidades.confirmacao' => ['pt' => 'Confirmação', 'en' => 'Confirmation', 'es' => 'Confirmación'], 'responsabilidades.confirmar_alteracoes' => ['pt' => 'Confirma as alterações de responsabilidades?', 'en' => 'Confirm the responsibility changes?', 'es' => '¿Confirma los cambios de responsabilidades?'], 'responsabilidades.botao.cancelar' => ['pt' => 'Cancelar', 'en' => 'Cancel', 'es' => 'Cancelar'], 'responsabilidades.botao.confirmar' => ['pt' => 'Confirmar', 'en' => 'Confirm', 'es' => 'Confirmar']]) . '<script src="../assets/js/treinamento-ml-responsabilidades.js?v=2"></script><script src="../assets/js/responsabilidades-permissoes.js?v=1"></script>';
    echo '<script>(function(){var u=' . json_encode($assignedUserIds, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) . ',g=' . json_encode($assignedGroupIds, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) . ';document.querySelector("#addRow")?.addEventListener("click",function(){var row=document.querySelector("#responsibilityTable tbody tr:last-child");if(!row)return;[["CODUSUARIO",u],["CODGRUPO",g]].forEach(function(pair){var s=Array.from(row.querySelectorAll("select")).find(function(x){return x.name.indexOf("["+pair[0]+"]")>=0;});if(!s)return;Array.from(s.options).forEach(function(o){if(o.value&&pair[1].indexOf(String(o.value))>=0)o.remove();});});});})();</script>';
});
?><!doctype html><html lang="<?= IdiomaService::idioma() === 'pt' ? 'pt-BR' : IdiomaService::idioma() ?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?= htmlspecialchars(IdiomaService::t('responsabilidades.titulo', ['pt' => 'Responsabilidades', 'en' => 'Responsibilities', 'es' => 'Responsabilidades']), ENT_QUOTES, 'UTF-8') ?></title><link rel="stylesheet" href="../assets/vendor/bootstrap/css/bootstrap.min.css?v=2"><link rel="stylesheet" href="../assets/vendor/bootstrap-icons/bootstrap-icons.css?v=2"><link rel="stylesheet" href="../assets/css/app.css?v=1"><?php require_once dirname(__DIR__) . '/components/pagina_padrao.php'; greenPortalEstiloPagina(); ?></head><body class="p-3 bg-light"><main class="container-fluid"><h4><i class="bi bi-people me-2"></i><?= htmlspecialchars(IdiomaService::t('responsabilidades.titulo', ['pt' => 'Responsabilidades', 'en' => 'Responsibilities', 'es' => 'Responsabilidades']), ENT_QUOTES, 'UTF-8') ?></h4><p class="text-muted"><?= htmlspecialchars(IdiomaService::t('responsabilidades.treinamento', ['pt' => 'Treinamento', 'en' => 'Training', 'es' => 'Capacitación']), ENT_QUOTES, 'UTF-8') ?> <?= $e($id) ?> — <?= $e($context['DSCTREINAMENTO'] ?? '') ?></p><?php if ($message): ?><div class="alert alert-success py-2"><?= $e($message) ?></div><?php endif; ?><?php if ($error): ?><div class="alert alert-danger py-2"><?= $e($error) ?></div><?php endif; ?><form method="post" id="responsibilityForm"><input type="hidden" name="action" value="save_rows"><div class="d-flex gap-2 mb-2"><button type="button" class="btn btn-sm btn-outline-primary" id="addRow"><i class="bi bi-plus-lg me-1"></i><?= htmlspecialchars(IdiomaService::t('responsabilidades.botao.incluir', ['pt' => 'Incluir', 'en' => 'Add', 'es' => 'Incluir']), ENT_QUOTES, 'UTF-8') ?></button><button type="button" class="btn btn-sm btn-outline-danger" id="deleteRow" disabled><i class="bi bi-trash me-1"></i><?= htmlspecialchars(IdiomaService::t('responsabilidades.botao.excluir', ['pt' => 'Excluir', 'en' => 'Delete', 'es' => 'Eliminar']), ENT_QUOTES, 'UTF-8') ?></button><button type="submit" class="btn btn-sm btn-success"><i class="bi bi-check2 me-1"></i><?= htmlspecialchars(IdiomaService::t('responsabilidades.botao.confirmar', ['pt' => 'Confirmar', 'en' => 'Confirm', 'es' => 'Confirmar']), ENT_QUOTES, 'UTF-8') ?></button><button type="button" class="btn btn-sm btn-outline-secondary" onclick="window.close()"><?= htmlspecialchars(IdiomaService::t('responsabilidades.botao.cancelar', ['pt' => 'Cancelar', 'en' => 'Cancel', 'es' => 'Cancelar']), ENT_QUOTES, 'UTF-8') ?></button></div><div class="table-responsive border rounded bg-white"><table class="table table-sm align-middle mb-0" id="responsibilityTable"><thead class="table-light"><tr><th><?= htmlspecialchars(IdiomaService::t('responsabilidades.coluna.finalidade', ['pt' => 'Finalidade', 'en' => 'Purpose', 'es' => 'Finalidad']), ENT_QUOTES, 'UTF-8') ?></th><th><?= htmlspecialchars(IdiomaService::t('responsabilidades.coluna.destino', ['pt' => 'Destino', 'en' => 'Assigned to', 'es' => 'Destino']), ENT_QUOTES, 'UTF-8') ?></th><th><?= htmlspecialchars(IdiomaService::t('responsabilidades.coluna.responsavel', ['pt' => 'Responsável', 'en' => 'Responsible', 'es' => 'Responsable']), ENT_QUOTES, 'UTF-8') ?></th><th><?= htmlspecialchars(IdiomaService::t('responsabilidades.coluna.prioridade', ['pt' => 'Prioridade', 'en' => 'Priority', 'es' => 'Prioridad']), ENT_QUOTES, 'UTF-8') ?></th><th><?= htmlspecialchars(IdiomaService::t('responsabilidades.coluna.principal', ['pt' => 'Principal', 'en' => 'Main', 'es' => 'Principal']), ENT_QUOTES, 'UTF-8') ?></th><th><?= htmlspecialchars(IdiomaService::t('responsabilidades.coluna.vigencia', ['pt' => 'Vigência', 'en' => 'Validity', 'es' => 'Vigencia']), ENT_QUOTES, 'UTF-8') ?></th></tr></thead><tbody><?php foreach ($rows as $row): $key=(int)$row['CODATRIBUICAO']; ?><tr data-row-key="<?= $key ?>"><td><select class="form-select form-select-sm" name="rows[<?= $key ?>][CODTIPORESPONSABILIDADE]"><?php foreach ($types as $type): ?><option value="<?= $e($type['CODTIPORESPONSABILIDADE']) ?>"<?= (string)$type['CODIGO']===(string)$row['TIPO_CODIGO']?' selected':'' ?>><?= $e($type['NOME']) ?></option><?php endforeach; ?></select></td><td><select class="form-select form-select-sm js-destination" name="rows[<?= $key ?>][TIPO_DESTINO]"><option value="USUARIO"<?= $row['TIPO_DESTINO']==='USUARIO'?' selected':'' ?>><?= htmlspecialchars(IdiomaService::t('responsabilidades.destino.usuario', ['pt' => 'Usuário', 'en' => 'User', 'es' => 'Usuario']), ENT_QUOTES, 'UTF-8') ?></option><option value="GRUPO"<?= $row['TIPO_DESTINO']==='GRUPO'?' selected':'' ?>><?= htmlspecialchars(IdiomaService::t('responsabilidades.destino.grupo', ['pt' => 'Grupo', 'en' => 'Group', 'es' => 'Grupo']), ENT_QUOTES, 'UTF-8') ?></option></select></td><td><?= $e($row['RESPONSAVEL_EXIBICAO']) ?><input type="hidden" name="rows[<?= $key ?>][CODUSUARIO]" value="<?= $e($row['CODUSUARIO']) ?>"><input type="hidden" name="rows[<?= $key ?>][CODGRUPO]" value="<?= $e($row['CODGRUPO']) ?>"></td><td><input class="form-control form-control-sm" type="number" name="rows[<?= $key ?>][PRIORIDADE]" value="<?= $e($row['PRIORIDADE']) ?>"></td><td><input type="checkbox" name="rows[<?= $key ?>][PRINCIPAL]" value="1"<?= !empty($row['PRINCIPAL'])?' checked':'' ?>></td><td><input class="form-control form-control-sm" type="date" name="rows[<?= $key ?>][VALIDO_DE]" value="<?= $e($row['VALIDO_DE']) ?>"></td></tr><?php endforeach; ?></tbody></table></div></form></main><script>const types=<?= json_encode($types,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES) ?>,users=<?= json_encode($users,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES) ?>,groups=<?= json_encode($groups,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES) ?>;let seq=0,selected=null;const tbody=document.querySelector('#responsibilityTable tbody');function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));}function options(a,id,label){return '<option value=""><?= htmlspecialchars(IdiomaService::t('responsabilidades.selecione', ['pt' => 'Selecione', 'en' => 'Select', 'es' => 'Seleccione']), ENT_QUOTES, 'UTF-8') ?></option>'+a.map(x=>'<option value="'+esc(x[id])+'">'+esc(x[label])+'</option>').join('');}function mark(row){document.querySelectorAll('#responsibilityTable tr').forEach(x=>x.classList.remove('table-active'));if(row){row.classList.add('table-active');selected=row;document.querySelector('#deleteRow').disabled=String(row.dataset.rowKey).startsWith('novo_')?false:<?= $permission['pode_excluir']?'false':'true' ?>;}}document.querySelectorAll('#responsibilityTable tbody tr').forEach(r=>r.addEventListener('click',()=>mark(r)));document.querySelector('#deleteRow').addEventListener('click',()=>{if(selected)selected.remove();mark(null);});document.querySelector('#addRow').addEventListener('click',()=>{let k='novo_'+(++seq),r=document.createElement('tr');r.dataset.rowKey=k;r.innerHTML='<td><select class="form-select form-select-sm" name="rows['+k+'][CODTIPORESPONSABILIDADE]">'+types.map(x=>'<option value="'+esc(x.CODTIPORESPONSABILIDADE)+'">'+esc(x.NOME)+'</option>').join('')+'</select></td><td><select class="form-select form-select-sm" name="rows['+k+'][TIPO_DESTINO]"><option value="USUARIO"><?= htmlspecialchars(IdiomaService::t('responsabilidades.destino.usuario', ['pt' => 'Usuário', 'en' => 'User', 'es' => 'Usuario']), ENT_QUOTES, 'UTF-8') ?></option><option value="GRUPO"><?= htmlspecialchars(IdiomaService::t('responsabilidades.destino.grupo', ['pt' => 'Grupo', 'en' => 'Group', 'es' => 'Grupo']), ENT_QUOTES, 'UTF-8') ?></option></select></td><td><select class="form-select form-select-sm" name="rows['+k+'][CODUSUARIO]">'+options(users,'CODUSUARIO','NOME')+'</select><input type="hidden" name="rows['+k+'][CODGRUPO]" value=""></td><td><input class="form-control form-control-sm" type="number" name="rows['+k+'][PRIORIDADE]" value="0"></td><td><input type="checkbox" name="rows['+k+'][PRINCIPAL]" value="1"></td><td><input class="form-control form-control-sm" type="date" name="rows['+k+'][VALIDO_DE]" value="<?= date('Y-m-d') ?>"></td>';tbody.appendChild(r);r.addEventListener('click',()=>mark(r));mark(r);});</script></body></html>
